'use strict';

// MODULES //

var tape = require( 'tape' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var isFunction = require( '@stdlib/assert/is-function' );
var namedtypedtuple = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof namedtypedtuple, 'function', 'main export is a function' );
	t.end();
});

tape( 'a tuple factory has a `fromObject` method', function test( t ) {
	var Point;

	Point = namedtypedtuple( [ 'x', 'y' ] );

	t.strictEqual( hasOwnProp( Point, 'fromObject' ), true, 'returns expected value' );
	t.strictEqual( isFunction( Point.fromObject ), true, 'returns expected value' );
	t.end();
});

tape( 'the method throws an error if invoked with a `this` context which is not the host tuple factory', function test( t ) {
	var values;
	var Point;
	var opts;
	var i;

	Point = namedtypedtuple( [ 'x', 'y' ] );

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			opts = {
				'x': 1,
				'y': 2
			};
			return Point.fromObject.call( value, opts );
		};
	}
});

tape( 'the method throws an error if provided a first argument which is not an object', function test( t ) {
	var values;
	var Point;
	var i;

	Point = namedtypedtuple( [ 'x', 'y' ] );

	values = [
		'5',
		5,
		3.14,
		NaN,
		true,
		false,
		null,
		void 0
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return Point.fromObject( value );
		};
	}
});

tape( 'the method throws an error if provided a second argument which is not a function', function test( t ) {
	var values;
	var Point;
	var opts;
	var i;

	Point = namedtypedtuple( [ 'x', 'y' ] );

	values = [
		'5',
		3.14,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[]
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			opts = {
				'x': 1,
				'y': 2
			};
			return Point.fromObject( opts, value );
		};
	}
});

tape( 'the method creates a new tuple from an object', function test( t ) {
	var Point;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = Point.fromObject({
		'x': 10,
		'y': 20,
		'z': 30
	});

	t.strictEqual( p[ 0 ], 10, 'returns expected value' );
	t.strictEqual( p[ 1 ], 20, 'returns expected value' );
	t.strictEqual( p[ 2 ], 30, 'returns expected value' );
	t.deepEqual( p.fields, [ 'x', 'y', 'z' ], 'returns expected value' );
	t.end();
});

tape( 'the method ignores object properties which are not tuple fields', function test( t ) {
	var Point;
	var p;

	Point = namedtypedtuple( [ 'x', 'y' ] );
	p = Point.fromObject({
		'x': 10,
		'y': 20,
		'extra': 999
	});

	t.strictEqual( p[ 0 ], 10, 'returns expected value' );
	t.strictEqual( p[ 1 ], 20, 'returns expected value' );
	t.end();
});

tape( 'the method sets missing fields to zero', function test( t ) {
	var Point;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = Point.fromObject({
		'x': 10
	});

	t.strictEqual( p[ 0 ], 10, 'returns expected value' );
	t.strictEqual( p[ 1 ], 0, 'returns expected value' );
	t.strictEqual( p[ 2 ], 0, 'returns expected value' );
	t.end();
});

tape( 'the method creates a new tuple from an object using a callback', function test( t ) {
	var Point;
	var opts;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	opts = {
		'x': 10,
		'y': 20,
		'z': 30
	};
	p = Point.fromObject( opts, fcn );

	t.strictEqual( p[ 0 ], 20, 'returns expected value' );
	t.strictEqual( p[ 1 ], 40, 'returns expected value' );
	t.strictEqual( p[ 2 ], 60, 'returns expected value' );
	t.end();

	function fcn( v ) {
		return v * 2;
	}
});

tape( 'the callback is invoked with two arguments', function test( t ) {
	var fieldNames;
	var values;
	var Point;
	var opts;

	values = [];
	fieldNames = [];

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	opts = {
		'x': 10,
		'y': 20,
		'z': 30
	};
	Point.fromObject( opts, fcn );

	t.deepEqual( values, [ 10, 20, 30 ], 'returns expected value' );
	t.deepEqual( fieldNames, [ 'x', 'y', 'z' ], 'returns expected value' );
	t.end();

	function fcn( v, f ) {
		values.push( v );
		fieldNames.push( f );
		return v;
	}
});

tape( 'the method supports providing a callback execution context', function test( t ) {
	var Point;
	var opts;
	var ctx;

	ctx = {
		'count': 0
	};
	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	opts = {
		'x': 10,
		'y': 20,
		'z': 30
	};
	Point.fromObject( opts, fcn, ctx );

	t.strictEqual( ctx.count, 3, 'returns expected value' );
	t.end();

	function fcn( v ) {
		this.count += 1; // eslint-disable-line no-invalid-this
		return v;
	}
});
